// A simple random-bit generator struct.
#[derive(Debug, Clone)]
pub struct Generator {
    /// Indicates whether the generator has been initialized.
    pub initialized: bool,
    /// The optional seed as provided by the user.
    pub seed: Option<u64>,
    /// Internal 64-bit state derived from the seed.
    pub state: u64,
}

/// Compute a 64-bit internal state from an optional seed.
/// If a seed is provided, this function guarantees the returned state is non-zero.
/// If no seed is provided, the returned state may be zero.
pub fn compute_state(seed: Option<u64>) -> u64 {
    match seed {
        // Force at least one bit set so the state is never zero.
        Some(s) => s | 1,
        None => 0,
    }
}

/// Construct a new generator, mark it initialized, store the seed,
/// and derive its internal state via `compute_state`.
pub fn default_rng(seed: Option<u64>) -> Generator {
    let state = compute_state(seed);
    Generator {
        initialized: true,
        seed,
        state,
    }
}

